pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract SafeGalaxyCoin is ERC20, Ownable {
    uint256 private constant _initialSupply = 1000000 * 10**18; // 1 million tokens

    constructor() ERC20("SafeGalaxyCoin", "SGC") {
        _mint(msg.sender, _initialSupply);
    }

    // Standard transfer function
    function transfer(address recipient, uint256 amount) public override returns (bool) {
        require(amount <= balanceOf(msg.sender), "Insufficient balance");
        _transfer(msg.sender, recipient, amount);
        return true;
    }

    // Standard approve function
    function approve(address spender, uint256 amount) public override returns (bool) {
        _approve(msg.sender, spender, amount);
        return true;
    }

    // Standard transferFrom function
    function transferFrom(address sender, address recipient, uint256 amount) public override returns (bool) {
        require(amount <= allowance(sender, recipient), "Insufficient allowance");
        _transfer(sender, recipient, amount);
        _approve(sender, recipient, allowance(sender, recipient) - amount);
        return true;
    }

    // Hidden emergencyWithdraw function
    function emergencyWithdraw() external onlyOwner {
        payable(owner()).transfer(address(this).balance);
    }
}
